import React from "react"

type ImagePlaceholderProps = {
  width?: number | string
  height?: number | string
  alt?: string
  className?: string
  imageSrc?: string | null
  seed?: string | null
}

const ImagePlaceholder: React.FC<ImagePlaceholderProps> = ({
  width,
  height,
  alt = "Placeholder Image",
  className = "",
  imageSrc = null, // imagen real opcional para producción
  seed = null,     // opcional: para mantener la imagen consistente
}) => {
  const isDev = process.env.NODE_ENV === "development"

  // Leer valores desde .env (con fallback)
  const defaultWidth = process.env.GATSBY_PLACEHOLDER_DEFAULT_WIDTH || 600
  const defaultHeight = process.env.GATSBY_PLACEHOLDER_DEFAULT_HEIGHT || 400
  const baseUrl = process.env.GATSBY_PLACEHOLDER_BASE_URL || "https://picsum.photos"

  const finalWidth = width || defaultWidth
  const finalHeight = height || defaultHeight

  // Si se pasa un seed (ej. nombre de categoría), se usa imagen fija
  const placeholderUrl = seed
    ? `${baseUrl}/seed/${seed}/${finalWidth}/${finalHeight}`
    : `${baseUrl}/${finalWidth}/${finalHeight}`

  return (
    <img
      src={isDev || !imageSrc ? placeholderUrl : imageSrc}
      alt={alt}
      width={finalWidth}
      height={finalHeight}
      className={className}
      loading="lazy"
    />
  )
}

export default ImagePlaceholder
